export default JSON.parse("{\"id\":\"mindfulness_handout_4\",\"module\":\"Mindfulness\",\"module_category\":\"Mindfulness Skills\",\"item_type\":\"handout\",\"item_number\":\"4\",\"title\":\"Taking Hold of Your Mind: \u201cWhat\u201d Skills Observe \\u0003 \u0089 Notice your body sensations (coming through your eyes, ears, nose, skin, and tongue).\",\"source_marker\":\"Mindfulness Handout 4   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"source_pdf_pages\":[77],\"source_book_pages\":[\"53\"],\"related_references\":[\"Mindfulness Worksheets 2\u20132c, 4\u20134b\"],\"is_example\":false,\"fillable_html_created\":false,\"keywords\":[\"Hold\",\"Mind\",\"Notice\",\"Observe\",\"Skills\",\"Taking\",\"What\",\"Your\",\"body\",\"coming\",\"ears\",\"eyes\",\"nose\",\"sensations\",\"skin\",\"through\",\"tongue\",\"your\"],\"pages\":[{\"pdf_page\":77,\"book_page\":\"53\",\"text\":\"53\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nMindfulness Handout 4   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\\nTaking Hold of Your Mind: \u201cWhat\u201d Skills\\nObserve\\n\\u0003\\n\u0089 Notice your body sensations (coming through your eyes, ears, nose, skin, and tongue).\\n\\u0003\\n\u0089 Pay attention on purpose, to the present moment.\\n\\u0003\\n\u0089 Control your attention, but not what you see. Push away nothing. Cling to nothing.\\n\\u0003\\n\u0089 Practice wordless watching: Watch thoughts come into your mind and let them slip right by\\nlike clouds in the sky. Notice each feeling, rising and falling, like waves in the ocean.\\n\\u0003\\n\u0089 Observe both inside and outside yourself.\\nDescribe\\n\\u0003\\n\u0089 Put words on the experience. When a feeling or thought arises, or you do something,\\nacknowledge it. For example, say in your mind, \u201cSadness has just enveloped me,\u201d or \u201cStomach\\nmuscles tightening,\u201c or \u201cA thought \u2018I can\u2019t do this\u2019 has come into my mind.\u201d\\n\\u0003\\n\u0089 Label what you observe. Put a name on your feelings. Label a thought as just a thought, a\\nfeeling as just a feeling, an action as just an action.\\n\\u0003\\n\u0089 Unglue your interpretations and opinions from the facts. Describe the \u201cwho, what, when,\\nand where\u201d that you observe. Just the facts.\\n\\u0003\\n\u0089 Remember, If you can\u2019t observe it through your senses, you can\u2019t describe it.\\nParticipate\\n\\u0003\\n\u0089 Throw yourself completely into activities of the current moment. Do not separate yourself\\nfrom what is going on in the moment (dancing, cleaning, talking to a friend, feeling happy or\\nfeeling sad).\\n\\u0003\\n\u0089 Become one with whatever you are doing, completely forgetting yourself. Throw your\\nattention to the moment.\\n\\u0003\\n\u0089 Act intuitively from Wise Mind. Do just what is needed in each situation\u2014a skillful dancer on\\nthe dance floor, one with the music and your partner, neither willful nor sitting on your hands.\\n\\u0003\\n\u0089 Go with the flow. Respond with spontaneity.\"}],\"full_text\":\"\u00ab\\nMindfulness Handout 4   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\\nTaking Hold of Your Mind: \u201cWhat\u201d Skills\\nObserve\\n\\u0003\\n\u0089 Notice your body sensations (coming through your eyes, ears, nose, skin, and tongue).\\n\\u0003\\n\u0089 Pay attention on purpose, to the present moment.\\n\\u0003\\n\u0089 Control your attention, but not what you see. Push away nothing. Cling to nothing.\\n\\u0003\\n\u0089 Practice wordless watching: Watch thoughts come into your mind and let them slip right by\\nlike clouds in the sky. Notice each feeling, rising and falling, like waves in the ocean.\\n\\u0003\\n\u0089 Observe both inside and outside yourself.\\nDescribe\\n\\u0003\\n\u0089 Put words on the experience. When a feeling or thought arises, or you do something,\\nacknowledge it. For example, say in your mind, \u201cSadness has just enveloped me,\u201d or \u201cStomach\\nmuscles tightening,\u201c or \u201cA thought \u2018I can\u2019t do this\u2019 has come into my mind.\u201d\\n\\u0003\\n\u0089 Label what you observe. Put a name on your feelings. Label a thought as just a thought, a\\nfeeling as just a feeling, an action as just an action.\\n\\u0003\\n\u0089 Unglue your interpretations and opinions from the facts. Describe the \u201cwho, what, when,\\nand where\u201d that you observe. Just the facts.\\n\\u0003\\n\u0089 Remember, If you can\u2019t observe it through your senses, you can\u2019t describe it.\\nParticipate\\n\\u0003\\n\u0089 Throw yourself completely into activities of the current moment. Do not separate yourself\\nfrom what is going on in the moment (dancing, cleaning, talking to a friend, feeling happy or\\nfeeling sad).\\n\\u0003\\n\u0089 Become one with whatever you are doing, completely forgetting yourself. Throw your\\nattention to the moment.\\n\\u0003\\n\u0089 Act intuitively from Wise Mind. Do just what is needed in each situation\u2014a skillful dancer on\\nthe dance floor, one with the music and your partner, neither willful nor sitting on your hands.\\n\\u0003\\n\u0089 Go with the flow. Respond with spontaneity.\",\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/mindfulness/handouts/mindfulness_handout_4_taking_hold_of_your_mind_what_skills_observe_notice_your_body_sensatio.json\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Taking Hold of Your Mind: \u201cWhat\u201d Skills Observe \\u0003 \u0089 Notice your body sensations (coming through your eyes, ears, nose, skin, and tongue).\",\"domain\":\"mindfulness\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Mindfulness is allowed to be tiny, sensory-safe, and done from bed or wheelchair. Noticing without judging counts even when the day is messy.\",\"tiny_steps\":[\"Notice one body signal.\",\"Name one feeling or need.\",\"Find one neutral thing in the room.\",\"Return to the next safe action.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Use eyes-open grounding if closing eyes feels unsafe.\",\"Use quiet, low-scent, low-touch options for MCAS, trauma, and sensory overload.\",\"No posture requirement; lying down or supported sitting is valid.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not force stillness when it increases pain, panic, dysphoria, or trauma activation.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"mindfulness\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/02_DBT_Mindfulness/handouts/json/mindfulness_handout_4_taking_hold_of_your_mind_what_skills_observe_notice_your_body_sensatio.json\",\"shared_output_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_4_taking_hold_of_your_mind_what_skills_observe_notice_b277ebd2.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"shared_json_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_4_taking_hold_of_your_mind_what_skills_observe_notice_b277ebd2.json\"}");
